document.addEventListener('input',e=>{if(e.target.id.startsWith('product-')&&$('#product-name')){state.rewardDraft=rewardInput();save()}if(e.target.dataset.draft){state.drafts[e.target.dataset.draft]=e.target.value;save()}if(e.target.id==='question-answer')saveQuestion();if(e.target.dataset.return){state.returnAnswers[e.target.dataset.return]=e.target.value;save()}if(e.target.id==='review-note'){state.review.note=e.target.value;save()}if(e.target.id==='review-answer'){const r=state.records.find(r=>r.id===state.diaryId)||diaryRecord();if(r){state.drafts['review@'+r.id]=e.target.value;save()}}});
document.addEventListener('change',e=>{if(e.target.id==='new-plan-when')scheduleFields();if(e.target.id==='product-type'){$('#product-duration').hidden=e.target.value!=='time';state.rewardDraft=rewardInput();save()}if(e.target.id==='question-group-select'){saveQuestion();state.question.index=Number(e.target.value)*6;save();render()}if(e.target.id==='scenario'){const value=e.target.value;openDialog('切换体验场景？','<p>切换会载入一组新的虚构状态。若已写审阅意见，可以先下载保存。</p>',()=>{closeDialog();scenario(value)},'载入场景');$('#scenario').value=state.scenario}if(e.target.id==='preview-day'&&/^\d{4}-\d{2}-\d{2}$/.test(e.target.value)){if(state.timer){e.target.value=state.day;return toast('先结束当前计时，再切换预览日期。')}state.day=e.target.value;state.diaryId=null;save();render()}});
